--Quering loaded  data for Business Analysis
select * from customer

-- 1. Revenue Analysis 
-- Compared total revenue generated by male and female customers.

select 
	gender, 
	SUM(purchase_amount) revenue
from customer
group by gender


-- 2. Discount & Spending Analysis ( sub_query)
-- Identified discount users whose purchase amounts were at or above the overall average.

select 
	customer_id,
	purchase_amount 
from customer 
where discount_applied = 'Yes' and purchase_amount >= (select Round(AVG(purchase_amount),2) from customer);

--Note : In order to get 2 digit avg metrics after decimal
select round(avg(purchase_amount),2) from customer


-- 3. Product Rating Analysis 
-- Ranked the top 5 products by average review rating.

select 
	item_purchased,
	round(avg(review_rating::numeric),2) as "Average Product Rating"
from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;

-- 4. Shipping Analysis
-- Compared average purchase amounts for Standard and Express shipping.

select 
	shipping_type, 
	round(AVG(purchase_amount),2)
from customer
where shipping_type in ('Standard','Express')
group by shipping_type;

-- 5. Subscription Analysis 
-- Compared customer counts, average spending, and total revenue between subscribers and non-subscribers.

select 
	subscription_status,
	count(customer_id) AS total_customers,
	round(AVG(purchase_amount),2) AS avg_spend,
	SUM(purchase_amount) AS total_revenue
from customer
group by subscription_status
order by total_revenue,avg_spend desc;

-- 6. Discount Dependency Analysis 
-- Identified the top 5 products by percentage of purchases with discounts applied.
SELECT 
	item_purchased,
	ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/COUNT(*),2) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;


-- 7. Customer Segmentation 
-- Classified customers into New, Returning, and Loyal segments based on previous purchases.

with customer_type as (
select 
	customer_id,
	previous_purchases,
case 
    when previous_purchases = 1 then 'New'
    when previous_purchases between 2 and 10 then 'Returning'
    else 'Loyal'
    end as customer_segment
from customer)
select 
	customer_segment,
	count(*) AS "Number of Customers" 
from customer_type 
group by customer_segment;


-- 8. Product Popularity Analysis 
-- Identified the top 3 most purchased products within each category.

with item_counts as (
    select category,
           item_purchased,
           count(customer_id) AS total_orders,
           row_number() over (partition by category order by count(customer_id) desc) as item_rank
    from customer
    group by category, item_purchased
)
select 
	item_rank,
	category, 
	item_purchased, 
	total_orders
from item_counts
where item_rank <=3;


-- 9. Repeat Buyer Analysis
-- Compared subscription status among customers with more than 5 previous purchases.

select 
	subscription_status,
	count(customer_id) AS repeat_buyers
from customer
where previous_purchases > 5
group by subscription_status;


-- 10. Age Group Revenue Analysis
-- Compared total revenue across customer age groups.

select 
    age_group,
    sum(purchase_amount) AS total_revenue
from customer
group by age_group
order by total_revenue desc;